{"implementation":"def solve(case):
    import math

    def is_int(value):
        return isinstance(value, int) and not isinstance(value, bool)

    def is_number(value):
        return (isinstance(value, (int, float)) and not isinstance(value, bool)
                and (not isinstance(value, float) or math.isfinite(value)))

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required case field")
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list) or not is_int(budget):
        raise ValueError("invalid case fields")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    allocations = []
    names = []
    importances = []
    capacities = []
    minimums = []
    seen = set()

    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("segment must be an object")
        required = ("name", "importance", "minimum", "capacity")
        if any(field not in segment for field in required):
            raise ValueError("missing required segment field")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str) or name in seen:
            raise ValueError("segment names must be unique strings")
        if not is_number(importance) or not is_int(minimum) or not is_int(capacity):
            raise ValueError("invalid segment field")
        if minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment bounds")
        seen.add(name)
        names.append(name)
        importances.append(importance)
        minimums.append(minimum)
        capacities.append(capacity)
        allocations.append(minimum)

    quota_sum = sum(minimums)
    capacity_sum = sum(capacities)
    if budget < quota_sum or budget > capacity_sum:
        raise ValueError("infeasible budget")

    remaining = budget - quota_sum
    while remaining:
        eligible = [i for i, allocation in enumerate(allocations)
                    if allocation < capacities[i]]
        if not eligible:
            raise ValueError("infeasible budget")
        index = max(eligible,
                    key=lambda i: (importances[i] / (allocations[i] + 1), -i))
        allocations[index] += 1
        remaining -= 1

    by_name = {names[i]: allocations[i] for i in range(len(names))}
    total = sum(allocations)
    if total != budget:
        raise ValueError("budget conservation failure")
    return {"allocations": allocations, "by_name": by_name, "total": total}
